import{_ as d,C as c,o as a,c as p,a0 as i,b as o,w as t,a as n,E as l,a1 as s}from"./chunks/framework.CzVS_xMp.js";const h="/ai-data-center-systems/assets/routing-for-ai-fabrics-map.TO8w4UXU.svg",f="/ai-data-center-systems/assets/ebgp-underlay-path-diversity.C8Uotze_.svg",u="/ai-data-center-systems/assets/deterministic-routing-planes.CKrzxh69.svg",A="/ai-data-center-systems/assets/tenant-server-routing-traffic-engineering.rZtbBe0F.svg",w=JSON.parse('{"title":"Chapter 8: IP Routing for AI/ML Fabrics","description":"","frontmatter":{},"headers":[],"relativePath":"network/chap08/index.md","filePath":"network/chap08/index.md","lastUpdated":1788490169000}'),g={name:"network/chap08/index.md"};function m(b,e,C,P,y,v){const r=c("Mermaid");return a(),p("div",null,[e[11]||(e[11]=i('<h1 id="chapter-8-ip-routing-for-ai-ml-fabrics" tabindex="-1">Chapter 8: IP Routing for AI/ML Fabrics <a class="header-anchor" href="#chapter-8-ip-routing-for-ai-ml-fabrics" aria-label="Permalink to &quot;Chapter 8: IP Routing for AI/ML Fabrics&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#why-ip-routing-matters-in-ai-fabrics">Why IP Routing Matters in AI Fabrics</a><ul><li><a href="#backend-and-frontend-routing-domains">Backend and Frontend Routing Domains</a></li><li><a href="#dynamic-ip-routing-options">Dynamic IP Routing Options</a></li></ul></li><li><a href="#ebgp-underlay-for-ai-data-centers">eBGP Underlay for AI Data Centers</a><ul><li><a href="#why-ebgp-is-common">Why eBGP Is Common</a></li><li><a href="#bgp-unnumbered">BGP Unnumbered</a></li><li><a href="#next-hop-rewrite-and-as-path">Next-Hop Rewrite and AS-PATH</a></li><li><a href="#bgp-asn-allocation">BGP ASN Allocation</a></li><li><a href="#bgp-add-path">BGP ADD-PATH</a></li><li><a href="#as-path-strip-and-replace">AS-PATH Strip and Replace</a></li><li><a href="#bgp-link-bandwidth-extended-community">BGP Link Bandwidth Extended Community</a></li><li><a href="#minimum-bgp-peers-per-prefix">Minimum BGP Peers per Prefix</a></li></ul></li><li><a href="#bgp-deterministic-path-forwarding-bgp-dpf">BGP Deterministic Path Forwarding, BGP-DPF</a><ul><li><a href="#logical-fabric-colors">Logical Fabric Colors</a></li><li><a href="#rail-optimized-and-rail-unified-dpf">Rail-Optimized and Rail-Unified DPF</a></li><li><a href="#session-coloring-and-colored-routes">Session Coloring and Colored Routes</a></li><li><a href="#evpn-vxlan-and-underlay-color">EVPN-VXLAN and Underlay Color</a></li></ul></li><li><a href="#rift-for-fat-tree-and-dragonfly-fabrics">RIFT for Fat-Tree and Dragonfly Fabrics</a><ul><li><a href="#rift-basics">RIFT Basics</a></li><li><a href="#dragonfly-and-dragonfly-sparse">Dragonfly and Dragonfly Sparse</a></li></ul></li><li><a href="#is-is-for-ai-fabrics">IS-IS for AI Fabrics</a><ul><li><a href="#optimal-distributed-flooding">Optimal Distributed Flooding</a></li><li><a href="#is-is-flexalgo">IS-IS FlexAlgo</a></li><li><a href="#flexalgo-compared-with-bgp-dpf">FlexAlgo Compared with BGP-DPF</a></li></ul></li><li><a href="#multi-tenancy-for-aiml-data-centers">Multi-Tenancy for AI/ML Data Centers</a><ul><li><a href="#network-level-multi-tenancy">Network-Level Multi-Tenancy</a></li><li><a href="#evpn-vxlan-multi-tenancy">EVPN-VXLAN Multi-Tenancy</a></li><li><a href="#server-level-multi-tenancy">Server-Level Multi-Tenancy</a></li><li><a href="#combining-server-and-network-multi-tenancy">Combining Server and Network Multi-Tenancy</a></li><li><a href="#dynamic-acl-based-multi-tenancy">Dynamic ACL-Based Multi-Tenancy</a></li></ul></li><li><a href="#extending-ip-routing-to-the-server">Extending IP Routing to the Server</a><ul><li><a href="#server-to-tor-ebgp">Server-to-ToR eBGP</a></li><li><a href="#virtual-bgp-route-reflector">Virtual BGP Route Reflector</a></li></ul></li><li><a href="#traffic-engineering-and-telemetry">Traffic Engineering and Telemetry</a></li><li><a href="#segment-routing-and-srv6">Segment Routing and SRv6</a><ul><li><a href="#segment-routing-basics">Segment Routing Basics</a></li><li><a href="#sr-mpls-vs-srv6">SR-MPLS vs. SRv6</a></li><li><a href="#srv6-segment-routing-header">SRv6 Segment Routing Header</a></li><li><a href="#compressed-sid-and-usid">Compressed SID and uSID</a></li></ul></li><li><a href="#routing-protocol-comparison">Routing Protocol Comparison</a></li><li><a href="#operational-validation-checklist">Operational Validation Checklist</a></li><li><a href="#chapter-summary">Chapter Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#qa">Q&amp;A</a></li><li><a href="#references">References</a></li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>This chapter explains routing choices for AI/ML data center fabrics.</p><p>The core idea is:</p><blockquote><p>AI fabric routing is no longer just reachability. It must support scale, fast convergence, path diversity, traffic engineering, tenant isolation, and workload-aware forwarding.</p></blockquote><p>The chapter focuses on these topics:</p><ul><li>eBGP underlay for three-stage and five-stage Clos fabrics</li><li>BGP unnumbered using IPv6 link-local next hops</li><li>BGP ASN allocation and AS-PATH behavior</li><li>BGP ADD-PATH and BGP Link Bandwidth Extended Community</li><li>BGP Deterministic Path Forwarding, DPF</li><li>RIFT for fat-tree and Dragonfly-style fabrics</li><li>IS-IS flood optimization and FlexAlgo</li><li>EVPN-VXLAN and server/GPU-level multi-tenancy</li><li>Extending routing to GPU servers</li><li>Controller-driven traffic engineering</li><li>Segment Routing, SRv6, and uSID</li></ul><p><img src="'+h+'" alt="Routing map for AI fabrics"></p><h2 id="why-ip-routing-matters-in-ai-fabrics" tabindex="-1">Why IP Routing Matters in AI Fabrics <a class="header-anchor" href="#why-ip-routing-matters-in-ai-fabrics" aria-label="Permalink to &quot;Why IP Routing Matters in AI Fabrics&quot;">​</a></h2><p>Earlier chapters covered topology, load balancing, and congestion control. Routing ties those pieces together.</p><p>In AI fabrics, the routing protocol must answer more than &quot;Can this prefix be reached?&quot;</p><p>It also affects:</p><ul><li>How quickly the fabric converges after a link or node failure</li><li>Whether ECMP has enough usable next hops</li><li>Whether unequal link speeds can be represented</li><li>Whether workload or tenant traffic can be pinned to selected paths</li><li>Whether multi-tenant overlays can be signaled</li><li>Whether fabric topology can be exposed to controllers or adaptive routing</li><li>Whether GPU servers can participate in routing directly</li></ul><h3 id="backend-and-frontend-routing-domains" tabindex="-1">Backend and Frontend Routing Domains <a class="header-anchor" href="#backend-and-frontend-routing-domains" aria-label="Permalink to &quot;Backend and Frontend Routing Domains&quot;">​</a></h3><p>AI data centers often separate backend and frontend concerns.</p><table tabindex="0"><thead><tr><th>Domain</th><th>Main Traffic</th><th>Common Routing Style</th></tr></thead><tbody><tr><td>Backend training fabric</td><td>GPU/NIC east-west RDMA, RoCEv2</td><td>Native IP eBGP, BGP-DPF, GLB, BGP link bandwidth, RIFT, IS-IS FlexAlgo</td></tr><tr><td>Frontend / inference fabric</td><td>User traffic, API serving, storage, tenant services</td><td>eBGP underlay plus EVPN-VXLAN overlay</td></tr><tr><td>Storage domain</td><td>Checkpoints, data loading, object or block storage</td><td>RoCEv2, NVMe/TCP, iSCSI, or other IP storage designs</td></tr></tbody></table><p>The same routing protocol can be used in both domains, but with different features. For example, backend eBGP may use weighted ECMP and BGP Link Bandwidth Extended Community, while frontend eBGP may carry EVPN-VXLAN services for tenant segmentation.</p><h3 id="dynamic-ip-routing-options" tabindex="-1">Dynamic IP Routing Options <a class="header-anchor" href="#dynamic-ip-routing-options" aria-label="Permalink to &quot;Dynamic IP Routing Options&quot;">​</a></h3><p>The chapter compares traditional and emerging routing choices.</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Basic Type</th><th>Strength</th><th>Concern</th></tr></thead><tbody><tr><td>eBGP</td><td>Path-vector</td><td>Scale, policy, multi-vendor adoption, loop prevention</td><td>Convergence and topology awareness need tuning</td></tr><tr><td>OSPF</td><td>Link-state IGP</td><td>Familiar, hierarchical, fast enough in many networks</td><td>Flooding, complexity, and less data center traction</td></tr><tr><td>IS-IS</td><td>Link-state IGP</td><td>Scalable, extensible TLVs, FlexAlgo, link-local behavior</td><td>Less common in enterprise/data center operations</td></tr><tr><td>RIFT</td><td>Fat-tree optimized IGP</td><td>Designed for Clos/fat-tree, fast convergence, disaggregation</td><td>Newer and less mature than BGP</td></tr><tr><td>Segment Routing</td><td>Source-routing architecture</td><td>Explicit path control and controller-driven TE</td><td>Header overhead, hardware support, operational complexity</td></tr></tbody></table><p>There is no universal best routing protocol. The right choice depends on topology, scale, operations, vendor support, convergence target, and traffic engineering needs.</p><hr><h2 id="ebgp-underlay-for-ai-data-centers" tabindex="-1">eBGP Underlay for AI Data Centers <a class="header-anchor" href="#ebgp-underlay-for-ai-data-centers" aria-label="Permalink to &quot;eBGP Underlay for AI Data Centers&quot;">​</a></h2><p>eBGP is widely used for large data center fabrics, including AI fabrics, because it scales well and has strong policy controls.</p><p>Typical AI fabric use:</p><ul><li>Three-stage Clos: leaf - spine - leaf</li><li>Five-stage Clos: leaf - spine - super-spine - spine - leaf</li><li>Backend native IP fabric for GPU RDMA traffic</li><li>Frontend underlay for EVPN-VXLAN overlays</li></ul><h3 id="why-ebgp-is-common" tabindex="-1">Why eBGP Is Common <a class="header-anchor" href="#why-ebgp-is-common" aria-label="Permalink to &quot;Why eBGP Is Common&quot;">​</a></h3><p>Benefits:</p><ul><li>Proven at cloud scale</li><li>Clear loop prevention through AS-PATH</li><li>Strong route policy controls</li><li>Works across vendors</li><li>Supports Clos, Dragonfly-like, and full-mesh variations</li><li>Can carry additional service families such as EVPN</li><li>Can be automated with per-rack or per-switch ASN plans</li></ul><p>Limitations:</p><ul><li>BGP was not originally designed as a link-state fabric protocol.</li><li>Native BGP has limited link/queue awareness.</li><li>Convergence can be slower than some IGPs.</li><li>Large topologies require careful ASN and policy design.</li><li>Advanced AI features often require extensions or route policies.</li></ul><h3 id="bgp-unnumbered" tabindex="-1">BGP Unnumbered <a class="header-anchor" href="#bgp-unnumbered" aria-label="Permalink to &quot;BGP Unnumbered&quot;">​</a></h3><p>BGP unnumbered simplifies leaf-spine peering by avoiding per-link IPv4 addressing.</p><p>The idea:</p><ul><li>Interfaces use IPv6 link-local addresses.</li><li>IPv6 Neighbor Discovery discovers neighbors.</li><li>BGP establishes TCP sessions over link-local addresses.</li><li>IPv4 prefixes can be advertised with IPv6 link-local next hops.</li><li>Extended Next Hop Encoding, RFC 5549, allows this behavior.</li></ul>',37)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-679",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0AsequenceDiagram%0A%20%20%20%20participant%20Leaf%20as%20Leaf%0A%20%20%20%20participant%20Spine%20as%20Spine%0A%0A%20%20%20%20Leaf-%3E%3ESpine%3A%20IPv6%20Neighbor%20Solicitation%0A%20%20%20%20Spine--%3E%3ELeaf%3A%20IPv6%20Neighbor%20Advertisement%0A%20%20%20%20Spine--%3E%3ELeaf%3A%20Router%20Advertisement%20%2F%20link-local%20info%0A%20%20%20%20Leaf-%3E%3ESpine%3A%20TCP%20SYN%20to%20BGP%20port%20179%0A%20%20%20%20Spine--%3E%3ELeaf%3A%20TCP%20SYN%2FACK%0A%20%20%20%20Leaf-%3E%3ESpine%3A%20BGP%20OPEN%20with%20capabilities%0A%20%20%20%20Spine--%3E%3ELeaf%3A%20BGP%20OPEN%20%2F%20KEEPALIVE%0A%20%20%20%20Leaf-%3E%3ESpine%3A%20BGP%20UPDATE%3A%20IPv4%20NLRI%2C%20IPv6%20link-local%20next%20hop%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=i('<p>Operational benefit:</p><ul><li>Fewer point-to-point addresses to allocate</li><li>Easier automation</li><li>Less per-link configuration</li><li>Good fit for fabrics with many leaf-spine links</li></ul><h3 id="next-hop-rewrite-and-as-path" tabindex="-1">Next-Hop Rewrite and AS-PATH <a class="header-anchor" href="#next-hop-rewrite-and-as-path" aria-label="Permalink to &quot;Next-Hop Rewrite and AS-PATH&quot;">​</a></h3><p>In eBGP, each hop normally rewrites the next hop and adds its ASN to AS-PATH.</p><p>Example:</p><ol><li>Leaf 1 originates a GPU server prefix.</li><li>Spine receives it and advertises it to Leaf 2.</li><li>Spine rewrites the next hop to itself.</li><li>AS-PATH is updated with the relevant AS sequence.</li></ol><p>This behavior helps loop prevention and policy, but it must be understood when designing deterministic forwarding, maintenance policies, and failure handling.</p><h3 id="bgp-asn-allocation" tabindex="-1">BGP ASN Allocation <a class="header-anchor" href="#bgp-asn-allocation" aria-label="Permalink to &quot;BGP ASN Allocation&quot;">​</a></h3><p>ASN design is important in AI fabrics.</p><p>Common patterns:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Description</th><th>Benefit</th><th>Risk</th></tr></thead><tbody><tr><td>Same ASN for all spines, unique ASN per leaf</td><td>Common eBGP Clos design</td><td>Simple loop prevention and origin identification</td><td>Requires planning for AS-PATH expectations</td></tr><tr><td>Unique ASN per spine and leaf</td><td>More granular identity</td><td>More explicit topology identity</td><td>Can create suboptimal forwarding under failures</td></tr><tr><td>iBGP with route reflectors</td><td>Same ASN across fabric</td><td>Avoids eBGP next-hop rewrite</td><td>Less common for cloud-style data center fabrics</td></tr></tbody></table><p>The chapter emphasizes that using the same ASN for spines and unique ASNs for ToR/leaf switches can help avoid suboptimal forwarding after failures because BGP loop prevention rejects routes containing repeated ASNs.</p><h3 id="bgp-add-path" tabindex="-1">BGP ADD-PATH <a class="header-anchor" href="#bgp-add-path" aria-label="Permalink to &quot;BGP ADD-PATH&quot;">​</a></h3><p>BGP normally advertises only the best path for a prefix. BGP ADD-PATH allows more than one path to be advertised.</p><p>Why this matters:</p><ul><li>More path diversity</li><li>Better redundancy</li><li>Better multipath visibility</li><li>Useful when route reflectors or policy otherwise hide alternate paths</li></ul><p>In AI fabrics, ADD-PATH can help preserve usable paths for GPU traffic where link diversity and rapid recovery matter.</p><h3 id="as-path-strip-and-replace" tabindex="-1">AS-PATH Strip and Replace <a class="header-anchor" href="#as-path-strip-and-replace" aria-label="Permalink to &quot;AS-PATH Strip and Replace&quot;">​</a></h3><p>AS-PATH strip and replace normalizes AS-PATH when private ASNs are used inside the data center and routes must be exchanged with a larger core network.</p><p>Uses:</p><ul><li>Hide internal private ASN details from the core</li><li>Normalize path length</li><li>Avoid exposing tenant or fabric-internal ASN design</li><li>Support multi-tenant or multi-domain routing boundaries</li></ul><p>This is mainly relevant at fabric borders or when connecting to a core IP network.</p><h3 id="bgp-link-bandwidth-extended-community" tabindex="-1">BGP Link Bandwidth Extended Community <a class="header-anchor" href="#bgp-link-bandwidth-extended-community" aria-label="Permalink to &quot;BGP Link Bandwidth Extended Community&quot;">​</a></h3><p>BGP Link Bandwidth Extended Community carries bandwidth information that can be used for weighted ECMP.</p><p>Example:</p><table tabindex="0"><thead><tr><th>Path</th><th style="text-align:right;">Link Bandwidth</th><th>Weighting Goal</th></tr></thead><tbody><tr><td>Path A</td><td style="text-align:right;">400G</td><td>Lower share</td></tr><tr><td>Path B</td><td style="text-align:right;">800G</td><td>Higher share</td></tr></tbody></table><p>If one next hop has twice the capacity, weighted ECMP can send more traffic to it. This is useful in mixed-speed fabrics or during transitions from 400G to 800G links.</p><p><img src="'+f+'" alt="eBGP underlay path diversity in an AI fabric"></p><h3 id="minimum-bgp-peers-per-prefix" tabindex="-1">Minimum BGP Peers per Prefix <a class="header-anchor" href="#minimum-bgp-peers-per-prefix" aria-label="Permalink to &quot;Minimum BGP Peers per Prefix&quot;">​</a></h3><p>Some designs require a minimum number of active BGP peers for a prefix to be considered usable.</p><p>Reason:</p><ul><li>Avoid advertising or using a destination when too few paths remain.</li><li>Protect workload performance when ECMP width has collapsed.</li><li>Keep GPU jobs away from partially degraded fabric areas.</li></ul><p>This is a routing-level guardrail for performance, not just reachability.</p><hr><h2 id="bgp-deterministic-path-forwarding-bgp-dpf" tabindex="-1">BGP Deterministic Path Forwarding, BGP-DPF <a class="header-anchor" href="#bgp-deterministic-path-forwarding-bgp-dpf" aria-label="Permalink to &quot;BGP Deterministic Path Forwarding, BGP-DPF&quot;">​</a></h2><p>BGP Deterministic Path Forwarding, BGP-DPF, provides deterministic path selection by associating traffic with logical fabric colors.</p><p>The goal is similar to traffic engineering:</p><ul><li>Divide one physical fabric into logical fabrics.</li><li>Pin selected traffic to a fabric color.</li><li>Use GPU ID, QP, tenant, or SLA to choose a path.</li><li>Keep elephant flows predictable.</li><li>Improve isolation between tenants or workloads.</li></ul><h3 id="logical-fabric-colors" tabindex="-1">Logical Fabric Colors <a class="header-anchor" href="#logical-fabric-colors" aria-label="Permalink to &quot;Logical Fabric Colors&quot;">​</a></h3><p><img src="'+u+'" alt="Deterministic routing planes for AI fabrics"></p><p>DPF can be implemented through:</p><ul><li>BGP communities</li><li>Colored route advertisement</li><li>Session coloring</li><li>Route policy</li><li>ASIC forwarding behavior that maps flow characteristics to a color</li></ul><h3 id="rail-optimized-and-rail-unified-dpf" tabindex="-1">Rail-Optimized and Rail-Unified DPF <a class="header-anchor" href="#rail-optimized-and-rail-unified-dpf" aria-label="Permalink to &quot;Rail-Optimized and Rail-Unified DPF&quot;">​</a></h3><p>BGP-DPF can be applied in both ROD and RUD designs.</p><table tabindex="0"><thead><tr><th>Design</th><th>DPF Use</th></tr></thead><tbody><tr><td>Rail-Optimized Design, ROD</td><td>Each rail can carry a specific logical fabric or tenant path</td></tr><tr><td>Rail-Unified Design, RUD</td><td>GPU ID, QP, or tenant can choose a logical fabric even when rails share leaf groups</td></tr></tbody></table><p>In a RUD design, DPF becomes especially useful because multiple GPU/NIC positions may share the same physical leaf. The fabric needs a logical way to keep selected flows separated.</p><h3 id="session-coloring-and-colored-routes" tabindex="-1">Session Coloring and Colored Routes <a class="header-anchor" href="#session-coloring-and-colored-routes" aria-label="Permalink to &quot;Session Coloring and Colored Routes&quot;">​</a></h3><p>DPF can color the BGP session or the routes carried over the session.</p><p>Session coloring:</p><ul><li>A BGP peer/session belongs to a color such as black or gray.</li><li>Routes learned over that session are associated with that color.</li><li>Forwarding can select color-specific next hops.</li></ul><p>Colored route advertisement:</p><ul><li>Server or leaf advertises a prefix with color metadata.</li><li>Fabric uses that color to select the logical path.</li><li>A tenant or GPU workload can be mapped to a deterministic fabric.</li></ul><h3 id="evpn-vxlan-and-underlay-color" tabindex="-1">EVPN-VXLAN and Underlay Color <a class="header-anchor" href="#evpn-vxlan-and-underlay-color" aria-label="Permalink to &quot;EVPN-VXLAN and Underlay Color&quot;">​</a></h3><p>BGP-DPF can correlate overlay tenants with underlay colors.</p><p>Example:</p><ul><li>Tenant Black uses MAC-VRF Black.</li><li>Tenant Gray uses MAC-VRF Gray.</li><li>Tenant Black overlay is mapped to Underlay Fabric Black.</li><li>Tenant Gray overlay is mapped to Underlay Fabric Gray.</li></ul>',56)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1153",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20tenant%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20overlay%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20underlay%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20TB%5BTenant%20Black%5D%3A%3A%3Atenant%0A%20%20%20%20TG%5BTenant%20Gray%5D%3A%3A%3Atenant%0A%20%20%20%20MB%5BMAC-VRF%20Black%3Cbr%2F%3EEVPN-VXLAN%5D%3A%3A%3Aoverlay%0A%20%20%20%20MG%5BMAC-VRF%20Gray%3Cbr%2F%3EEVPN-VXLAN%5D%3A%3A%3Aoverlay%0A%20%20%20%20UB%5BUnderlay%20Color%20Black%5D%3A%3A%3Aunderlay%0A%20%20%20%20UG%5BUnderlay%20Color%20Gray%5D%3A%3A%3Aunderlay%0A%0A%20%20%20%20TB%20--%3E%20MB%20--%3E%20UB%0A%20%20%20%20TG%20--%3E%20MG%20--%3E%20UG%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=i('<p>This gives both tenant isolation and path isolation.</p><hr><h2 id="rift-for-fat-tree-and-dragonfly-fabrics" tabindex="-1">RIFT for Fat-Tree and Dragonfly Fabrics <a class="header-anchor" href="#rift-for-fat-tree-and-dragonfly-fabrics" aria-label="Permalink to &quot;RIFT for Fat-Tree and Dragonfly Fabrics&quot;">​</a></h2><p>RIFT, Routing in Fat Trees, is an IGP designed for fat-tree and Clos-like data center topologies.</p><h3 id="rift-basics" tabindex="-1">RIFT Basics <a class="header-anchor" href="#rift-basics" aria-label="Permalink to &quot;RIFT Basics&quot;">​</a></h3><p>RIFT combines two propagation styles:</p><table tabindex="0"><thead><tr><th>Direction</th><th>Behavior</th></tr></thead><tbody><tr><td>Northbound</td><td>Link-state flooding toward higher levels</td></tr><tr><td>Southbound</td><td>Distance-vector style routing toward lower levels</td></tr></tbody></table><p>Key benefits:</p><ul><li>Designed for fat-tree topology</li><li>Fast convergence</li><li>Automatic disaggregation on failure</li><li>Wide ECMP and UCMP support</li><li>Topology awareness</li><li>Metadata advertisements</li><li>Better fit for large Clos than general-purpose IGP flooding</li></ul>',9)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1240",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20leaf%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20spine%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20super%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20L1%5BLeaf%201%5D%3A%3A%3Aleaf%0A%20%20%20%20L2%5BLeaf%202%5D%3A%3A%3Aleaf%0A%20%20%20%20S1%5BSpine%201%5D%3A%3A%3Aspine%0A%20%20%20%20S2%5BSpine%202%5D%3A%3A%3Aspine%0A%20%20%20%20SS%5BSuper-spine%5D%3A%3A%3Asuper%0A%0A%20%20%20%20L1%20--%3E%7Cnorthbound%20link-state%7C%20S1%0A%20%20%20%20L2%20--%3E%7Cnorthbound%20link-state%7C%20S2%0A%20%20%20%20S1%20--%3E%7Cnorthbound%7C%20SS%0A%20%20%20%20S2%20--%3E%7Cnorthbound%7C%20SS%0A%20%20%20%20SS%20--%3E%7Csouthbound%20distance-vector%7C%20S1%0A%20%20%20%20SS%20--%3E%7Csouthbound%20distance-vector%7C%20S2%0A%20%20%20%20S1%20--%3E%7Csouthbound%7C%20L1%0A%20%20%20%20S2%20--%3E%7Csouthbound%7C%20L2%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=i('<h3 id="dragonfly-and-dragonfly-sparse" tabindex="-1">Dragonfly and Dragonfly Sparse <a class="header-anchor" href="#dragonfly-and-dragonfly-sparse" aria-label="Permalink to &quot;Dragonfly and Dragonfly Sparse&quot;">​</a></h3><p>The chapter discusses Dragonfly as a topology where groups connect to other groups through global links.</p><p>Benefits:</p><ul><li>Reduced network diameter</li><li>Lower hop count</li><li>Lower latency potential</li><li>High path diversity</li><li>Useful for HPC-like topologies</li></ul><p>Challenges:</p><ul><li>Cabling complexity</li><li>Group-to-group link planning</li><li>Workload placement sensitivity</li><li>Need for topology-aware routing</li><li>Less familiar operational model than Clos</li></ul><p>Dragonfly Sparse reduces some complexity by using leaf-spine Clos inside a group and connecting selected top-of-fabric nodes between groups.</p><p>RIFT is relevant here because it can encode topology information that traditional Clos-only assumptions may not support.</p><hr><h2 id="is-is-for-ai-fabrics" tabindex="-1">IS-IS for AI Fabrics <a class="header-anchor" href="#is-is-for-ai-fabrics" aria-label="Permalink to &quot;IS-IS for AI Fabrics&quot;">​</a></h2><p>IS-IS is a link-state IGP. The chapter presents it as an alternative to BGP and RIFT for AI backend fabrics, especially where fast convergence, dense topology optimization, and logical path computation matter.</p><h3 id="optimal-distributed-flooding" tabindex="-1">Optimal Distributed Flooding <a class="header-anchor" href="#optimal-distributed-flooding" aria-label="Permalink to &quot;Optimal Distributed Flooding&quot;">​</a></h3><p>Traditional link-state flooding can become expensive in dense topologies. IS-IS Optimal Distributed Flooding reduces unnecessary flooding by electing selected neighbors for update propagation.</p><p>Benefits:</p><ul><li>Less control-plane flooding</li><li>Faster convergence in dense leaf-spine designs</li><li>Reduced LSP fragment processing</li><li>More useful as spine count grows to 32, 64, or more</li></ul>',15)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1351",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20leaf%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20spine%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20chosen%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20L%5BLeaf%20announces%20new%20prefix%5D%3A%3A%3Aleaf%0A%20%20%20%20S1%5BSpine%201%5D%3A%3A%3Aspine%0A%20%20%20%20S2%5BSpine%202%3Cbr%2F%3Eselected%20flood%20neighbor%5D%3A%3A%3Achosen%0A%20%20%20%20S3%5BSpine%203%5D%3A%3A%3Aspine%0A%0A%20%20%20%20L%20-.-%3E%20S1%0A%20%20%20%20L%20%3D%3D%3E%7Cflood%20update%20here%7C%20S2%0A%20%20%20%20L%20-.-%3E%20S3%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[n(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=i('<h3 id="is-is-flexalgo" tabindex="-1">IS-IS FlexAlgo <a class="header-anchor" href="#is-is-flexalgo" aria-label="Permalink to &quot;IS-IS FlexAlgo&quot;">​</a></h3><p>FlexAlgo lets IS-IS compute multiple logical topologies over the same physical fabric.</p><p>Each FlexAlgo is defined by a Flexible Algorithm Definition, FAD:</p><ul><li>Calculation type</li><li>Metric type</li><li>Constraints</li></ul><p>Example:</p><table tabindex="0"><thead><tr><th>FlexAlgo</th><th>Constraint Goal</th><th>Possible Workload</th></tr></thead><tbody><tr><td>Default</td><td>Normal shortest path</td><td>General traffic</td></tr><tr><td>128</td><td>Low latency</td><td>Latency-sensitive collectives</td></tr><tr><td>129</td><td>High bandwidth</td><td>Elephant RDMA flows</td></tr><tr><td>130</td><td>Low congestion</td><td>Congestion-sensitive or premium workloads</td></tr></tbody></table>',6)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1442",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20physical%20fill%3A%235a3520%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20low%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20bw%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20cong%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20P%5BSame%20physical%20leaf-spine%20fabric%5D%3A%3A%3Aphysical%0A%20%20%20%20A128%5BFlexAlgo%20128%3Cbr%2F%3Elow%20latency%20plane%5D%3A%3A%3Alow%0A%20%20%20%20A129%5BFlexAlgo%20129%3Cbr%2F%3Ehigh%20bandwidth%20plane%5D%3A%3A%3Abw%0A%20%20%20%20A130%5BFlexAlgo%20130%3Cbr%2F%3Elow%20congestion%20plane%5D%3A%3A%3Acong%0A%0A%20%20%20%20P%20--%3E%20A128%0A%20%20%20%20P%20--%3E%20A129%0A%20%20%20%20P%20--%3E%20A130%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[n(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=i('<p>FlexAlgo can steer different AI workloads into different logical path planes without requiring SR-MPLS or SRv6 encapsulation for the basic pure-IP use case.</p><h3 id="flexalgo-compared-with-bgp-dpf" tabindex="-1">FlexAlgo Compared with BGP-DPF <a class="header-anchor" href="#flexalgo-compared-with-bgp-dpf" aria-label="Permalink to &quot;FlexAlgo Compared with BGP-DPF&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>BGP-DPF</th><th>IS-IS FlexAlgo</th></tr></thead><tbody><tr><td>Control input</td><td>BGP communities, route/session colors, policy</td><td>IS-IS TLVs and FAD constraints</td></tr><tr><td>Main abstraction</td><td>Logical fabric color</td><td>Algorithm-specific topology</td></tr><tr><td>Topology awareness</td><td>Policy-driven, BGP is not native link-state</td><td>Native link-state</td></tr><tr><td>Workload mapping</td><td>Tenant, GPU ID, QP, SLA</td><td>Metric/constraint-based plane</td></tr><tr><td>Best fit</td><td>BGP-based fabrics needing deterministic colors</td><td>IGP fabrics needing path diversity and fast convergence</td></tr></tbody></table><hr><h2 id="multi-tenancy-for-ai-ml-data-centers" tabindex="-1">Multi-Tenancy for AI/ML Data Centers <a class="header-anchor" href="#multi-tenancy-for-ai-ml-data-centers" aria-label="Permalink to &quot;Multi-Tenancy for AI/ML Data Centers&quot;">​</a></h2><p>Multi-tenancy appears when GPUs are shared between users, teams, customers, or services.</p><p>Reasons:</p><ul><li>Security isolation</li><li>Performance isolation</li><li>Capacity planning</li><li>GPU-as-a-Service, GPUaaS</li><li>Public or private cloud AI offerings</li><li>Separate training and inference tenants</li></ul><p><img src="'+A+'" alt="Tenant isolation, server routing, telemetry, and SRv6 traffic engineering"></p><h3 id="network-level-multi-tenancy" tabindex="-1">Network-Level Multi-Tenancy <a class="header-anchor" href="#network-level-multi-tenancy" aria-label="Permalink to &quot;Network-Level Multi-Tenancy&quot;">​</a></h3><p>The simplest model is dedicated physical resources:</p><ul><li>A tenant gets a full GPU server.</li><li>Each GPU/NIC port is connected to a rail leaf.</li><li>Switch ports are dedicated to that tenant.</li></ul><p>This is simple and strong from an isolation perspective, but it can waste resources if tenants do not need full servers or full rails.</p><h3 id="evpn-vxlan-multi-tenancy" tabindex="-1">EVPN-VXLAN Multi-Tenancy <a class="header-anchor" href="#evpn-vxlan-multi-tenancy" aria-label="Permalink to &quot;EVPN-VXLAN Multi-Tenancy&quot;">​</a></h3><p>EVPN-VXLAN can segment tenant traffic using:</p><table tabindex="0"><thead><tr><th>Object</th><th>Role</th></tr></thead><tbody><tr><td>VLAN</td><td>Local Layer 2 tenant mapping</td></tr><tr><td>VNI</td><td>VXLAN network identifier</td></tr><tr><td>MAC-VRF</td><td>Tenant Layer 2 forwarding instance</td></tr><tr><td>IP-VRF</td><td>Tenant Layer 3 routing instance</td></tr><tr><td>EVPN RT-2</td><td>MAC/IP host route advertisement</td></tr><tr><td>EVPN RT-5</td><td>IP prefix route advertisement</td></tr><tr><td>Routing VNI</td><td>Tenant L3 VXLAN tunnel identifier</td></tr></tbody></table>',16)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1668",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20tenant%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20evpn%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20fabric%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20TA%5BTenant%20A%20GPU%5D%3A%3A%3Atenant%0A%20%20%20%20TB%5BTenant%20B%20GPU%5D%3A%3A%3Atenant%0A%20%20%20%20VA%5BVLAN%20A%20%2F%20VNI%2010010%3Cbr%2F%3EMAC-VRF%20A%20%2F%20IP-VRF%20A%5D%3A%3A%3Aevpn%0A%20%20%20%20VB%5BVLAN%20B%20%2F%20VNI%2010020%3Cbr%2F%3EMAC-VRF%20B%20%2F%20IP-VRF%20B%5D%3A%3A%3Aevpn%0A%20%20%20%20F%5BShared%20leaf-spine%20fabric%5D%3A%3A%3Afabric%0A%0A%20%20%20%20TA%20--%3E%20VA%20--%3E%20F%0A%20%20%20%20TB%20--%3E%20VB%20--%3E%20F%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[n(" Loading... ",-1)])]),_:1})),e[17]||(e[17]=i('<p>The chapter describes using RT-5 EVPN IP instances between rails and using route servers at the spine layer. Tenant routes are defined at the ToR/leaf, while spines provide EVPN route reflection or route-server behavior.</p><h3 id="server-level-multi-tenancy" tabindex="-1">Server-Level Multi-Tenancy <a class="header-anchor" href="#server-level-multi-tenancy" aria-label="Permalink to &quot;Server-Level Multi-Tenancy&quot;">​</a></h3><p>Server vendors may provide GPU-level partitioning. The chapter uses NVIDIA MIG, Multi-Instance GPU, as the example.</p><p>MIG can partition one physical GPU into multiple GPU instances. Each instance can be assigned to a different tenant or workload.</p><p>Example:</p><table tabindex="0"><thead><tr><th>Physical GPU</th><th>Tenant Mapping</th></tr></thead><tbody><tr><td>MIG instance 1</td><td>Tenant 1</td></tr><tr><td>MIG instance 2</td><td>Tenant 2</td></tr><tr><td>MIG instance 3</td><td>Tenant 3</td></tr><tr><td>...</td><td>...</td></tr><tr><td>MIG instance 7</td><td>Tenant 7</td></tr></tbody></table><p>Inside the server, vGPU or MIG-level tenancy can be scheduled across servers with collective communication software such as NCCL or RCCL.</p><h3 id="combining-server-and-network-multi-tenancy" tabindex="-1">Combining Server and Network Multi-Tenancy <a class="header-anchor" href="#combining-server-and-network-multi-tenancy" aria-label="Permalink to &quot;Combining Server and Network Multi-Tenancy&quot;">​</a></h3><p>Server-level and network-level tenancy can be combined.</p><p>Example:</p><ul><li>A server has seven MIG instances.</li><li>Each MIG instance maps to a VLAN.</li><li>The ToR leaf has seven MAC-VRFs and seven EVPN IP-level instances.</li><li>Each tenant gets separate L2 tags, VNI, VRF, and routing policy.</li></ul><p>This creates end-to-end tenant isolation from GPU instance to fabric path.</p>',12)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1775",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20gpu%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20vlan%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20vrf%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20M1%5BMIG%201%3Cbr%2F%3ETenant%201%5D%3A%3A%3Agpu%0A%20%20%20%20M2%5BMIG%202%3Cbr%2F%3ETenant%202%5D%3A%3A%3Agpu%0A%20%20%20%20V1%5BVLAN%20101%3Cbr%2F%3EVNI%20100101%5D%3A%3A%3Avlan%0A%20%20%20%20V2%5BVLAN%20102%3Cbr%2F%3EVNI%20100102%5D%3A%3A%3Avlan%0A%20%20%20%20R1%5BMAC-VRF%20%2F%20IP-VRF%3Cbr%2F%3ETenant%201%5D%3A%3A%3Avrf%0A%20%20%20%20R2%5BMAC-VRF%20%2F%20IP-VRF%3Cbr%2F%3ETenant%202%5D%3A%3A%3Avrf%0A%0A%20%20%20%20M1%20--%3E%20V1%20--%3E%20R1%0A%20%20%20%20M2%20--%3E%20V2%20--%3E%20R2%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[n(" Loading... ",-1)])]),_:1})),e[18]||(e[18]=i('<h3 id="dynamic-acl-based-multi-tenancy" tabindex="-1">Dynamic ACL-Based Multi-Tenancy <a class="header-anchor" href="#dynamic-acl-based-multi-tenancy" aria-label="Permalink to &quot;Dynamic ACL-Based Multi-Tenancy&quot;">​</a></h3><p>Another approach is dynamic ACLs on the ToR data plane, driven by a tenant profile from a system such as RADIUS.</p><p>Benefits:</p><ul><li>Centralized policy</li><li>Potentially simpler than full EVPN-VXLAN in smaller designs</li><li>Can apply tenant rules directly at the ToR</li></ul><p>Limitations:</p><ul><li>TCAM scale can become a blocker.</li><li>ACL complexity grows with tenant count.</li><li>EVPN-VXLAN is usually more scalable for distributed tenant isolation.</li></ul><hr><h2 id="extending-ip-routing-to-the-server" tabindex="-1">Extending IP Routing to the Server <a class="header-anchor" href="#extending-ip-routing-to-the-server" aria-label="Permalink to &quot;Extending IP Routing to the Server&quot;">​</a></h2><p>The chapter also discusses extending routing to GPU servers.</p><p>Instead of treating servers as passive hosts, a GPU server can run a BGP stack and advertise prefixes to the fabric.</p><h3 id="server-to-tor-ebgp" tabindex="-1">Server-to-ToR eBGP <a class="header-anchor" href="#server-to-tor-ebgp" aria-label="Permalink to &quot;Server-to-ToR eBGP&quot;">​</a></h3><p>Use cases:</p><ul><li>Advertise service IPs from servers</li><li>Advertise host routes or anycast services</li><li>Improve failover through BGP withdraw</li><li>Keep end-to-end routing protocol behavior consistent</li><li>Avoid static host route models</li></ul>',13)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-1865",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20server%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20leaf%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20spine%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20S1%5BGPU%20server%201%3Cbr%2F%3EBGP%20ASN%5D%3A%3A%3Aserver%0A%20%20%20%20S2%5BGPU%20server%202%3Cbr%2F%3EBGP%20ASN%5D%3A%3A%3Aserver%0A%20%20%20%20L1%5BToR%20%2F%20Leaf%201%5D%3A%3A%3Aleaf%0A%20%20%20%20L2%5BToR%20%2F%20Leaf%202%5D%3A%3A%3Aleaf%0A%20%20%20%20SP%5BSpine%5D%3A%3A%3Aspine%0A%0A%20%20%20%20S1%20%3C--%3E%7CeBGP%7C%20L1%0A%20%20%20%20S2%20%3C--%3E%7CeBGP%7C%20L2%0A%20%20%20%20L1%20%3C--%3E%7Cfabric%20eBGP%7C%20SP%0A%20%20%20%20L2%20%3C--%3E%7Cfabric%20eBGP%7C%20SP%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[n(" Loading... ",-1)])]),_:1})),e[19]||(e[19]=i('<p>If a server-side service fails, the server can withdraw the prefix, and the fabric can stop forwarding traffic to it.</p><h3 id="virtual-bgp-route-reflector" tabindex="-1">Virtual BGP Route Reflector <a class="header-anchor" href="#virtual-bgp-route-reflector" aria-label="Permalink to &quot;Virtual BGP Route Reflector&quot;">​</a></h3><p>At larger scale, having every server peer directly with every relevant fabric node may be too heavy.</p><p>A virtual appliance BGP route reflector can:</p><ul><li>Reduce peering count</li><li>Centralize server route reflection</li><li>Advertise server service prefixes into spines</li><li>Provide a cleaner boundary between server routing and fabric routing</li></ul><p>This is especially useful for service prefixes such as anycast IPs.</p><hr><h2 id="traffic-engineering-and-telemetry" tabindex="-1">Traffic Engineering and Telemetry <a class="header-anchor" href="#traffic-engineering-and-telemetry" aria-label="Permalink to &quot;Traffic Engineering and Telemetry&quot;">​</a></h2><p>AI fabric traffic engineering can be distributed or controller-driven.</p><p>Distributed examples:</p><ul><li>ECMP</li><li>DLB</li><li>GLB</li><li>BGP-DPF</li><li>IS-IS FlexAlgo</li></ul><p>For the GLB-specific use of BGP NNHN and forwarding-plane heartbeats, see [Appendix: BGP-based Underlay and GLB NNHN](../glb-nnhn-bgp-underlay/.</p><p>Controller-driven examples:</p><ul><li>Controller receives fabric topology</li><li>Controller receives telemetry</li><li>Controller receives job scheduler intent</li><li>Controller computes preferred GPU-to-GPU paths</li><li>Controller pushes routing or policy updates</li></ul><p>Telemetry inputs:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Use</th></tr></thead><tbody><tr><td>Link utilization</td><td>Avoid hot links</td></tr><tr><td>Queue occupancy</td><td>Detect congestion pressure</td></tr><tr><td>PFC/ECN counters</td><td>Detect lossless fabric stress</td></tr><tr><td>sFlow or sampled flow data</td><td>Identify traffic patterns</td></tr><tr><td>Egress BGP statistics</td><td>Understand route and next-hop use</td></tr><tr><td>Active probes</td><td>Measure end-to-end path quality</td></tr><tr><td>Job scheduler metadata</td><td>Map workload to fabric policy</td></tr></tbody></table>',16)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-2046",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20scheduler%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20telemetry%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20controller%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20fabric%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20J%5BGPU%20job%20scheduler%3Cbr%2F%3Eplacement%20and%20SLA%5D%3A%3A%3Ascheduler%0A%20%20%20%20T%5BFabric%20telemetry%3Cbr%2F%3Elinks%2C%20queues%2C%20ECN%2FPFC%2C%20probes%5D%3A%3A%3Atelemetry%0A%20%20%20%20C%5BFabric%20controller%3Cbr%2F%3Epath%20computation%5D%3A%3A%3Acontroller%0A%20%20%20%20F%5BAI%20fabric%3Cbr%2F%3EBGP%2C%20DPF%2C%20SR%2C%20policy%5D%3A%3A%3Afabric%0A%0A%20%20%20%20J%20--%3E%20C%0A%20%20%20%20T%20--%3E%20C%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20F%20--%3E%20T%0A"})]),fallback:t(()=>[...e[8]||(e[8]=[n(" Loading... ",-1)])]),_:1})),e[20]||(e[20]=i('<hr><h2 id="segment-routing-and-srv6" tabindex="-1">Segment Routing and SRv6 <a class="header-anchor" href="#segment-routing-and-srv6" aria-label="Permalink to &quot;Segment Routing and SRv6&quot;">​</a></h2><p>Segment Routing, SR, is a source-routing architecture. The ingress node encodes path instructions in the packet, and transit nodes forward based on those instructions.</p><h3 id="segment-routing-basics" tabindex="-1">Segment Routing Basics <a class="header-anchor" href="#segment-routing-basics" aria-label="Permalink to &quot;Segment Routing Basics&quot;">​</a></h3><p>Important terms:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>SR domain</td><td>Network where Segment Routing is enabled</td></tr><tr><td>Segment</td><td>A node, link, adjacency, or instruction</td></tr><tr><td>SID</td><td>Segment Identifier</td></tr><tr><td>Node SID</td><td>Identifier for a node</td></tr><tr><td>Adjacency SID</td><td>Identifier for a specific link or adjacency</td></tr><tr><td>Anycast SID</td><td>Shared identifier for a group of nodes</td></tr><tr><td>EPE SID</td><td>Egress Peer Engineering SID</td></tr><tr><td>SR path</td><td>Ordered list of segments from ingress to egress</td></tr></tbody></table>',6)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-2138",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20node%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20sid%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20I%5BIngress%20leaf%5D%3A%3A%3Anode%0A%20%20%20%20S%5BSpine%3Cbr%2F%3ENode%20SID%205%5D%3A%3A%3Asid%0A%20%20%20%20E%5BEgress%20leaf%3Cbr%2F%3ENode%20SID%201%5D%3A%3A%3Asid%0A%20%20%20%20D%5BDestination%20server%5D%3A%3A%3Anode%0A%0A%20%20%20%20I%20--%3E%7Cpacket%20carries%20SID%205%2C%20SID%201%7C%20S%0A%20%20%20%20S%20--%3E%7Cpop%20SID%205%2C%20follow%20SID%201%7C%20E%0A%20%20%20%20E%20--%3E%7Cpop%20SID%201%7C%20D%0A"})]),fallback:t(()=>[...e[9]||(e[9]=[n(" Loading... ",-1)])]),_:1})),e[21]||(e[21]=i(`<p>SR lets a controller compute an explicit path and install instructions at ingress rather than relying only on local ECMP choices at each hop.</p><h3 id="sr-mpls-vs-srv6" tabindex="-1">SR-MPLS vs. SRv6 <a class="header-anchor" href="#sr-mpls-vs-srv6" aria-label="Permalink to &quot;SR-MPLS vs. SRv6&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Data Plane</th><th>How It Encodes SIDs</th><th>Notes</th></tr></thead><tbody><tr><td>SR-MPLS</td><td>MPLS label stack</td><td>Common in service provider networks</td></tr><tr><td>SRv6</td><td>IPv6 Segment Routing Header, SRH</td><td>Uses IPv6 extension header with segment list</td></tr></tbody></table><p>Control-plane information for Segment Routing can come from:</p><ul><li>IGP</li><li>BGP-LS</li><li>Controller topology database</li><li>Path Computation Element Protocol, PCEP</li></ul><h3 id="srv6-segment-routing-header" tabindex="-1">SRv6 Segment Routing Header <a class="header-anchor" href="#srv6-segment-routing-header" aria-label="Permalink to &quot;SRv6 Segment Routing Header&quot;">​</a></h3><p>SRv6 uses an IPv6 extension header called the Segment Routing Header, SRH.</p><p>The SRH sits between IPv6 and upper-layer payload such as UDP/RoCEv2.</p><p>Conceptual packet:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IPv6 header</span></span>
<span class="line"><span>SRH: segment list</span></span>
<span class="line"><span>UDP / RoCEv2 header</span></span>
<span class="line"><span>Payload</span></span></code></pre></div><p>SRv6 SID structure can include:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td>Locator</td><td>Identifies the node or location</td></tr><tr><td>Function</td><td>Encodes node, adjacency, or service behavior</td></tr><tr><td>Argument</td><td>Optional service or application metadata</td></tr></tbody></table><p>The chapter notes that SRv6 network programming lets the network encode a program of forwarding instructions into IPv6 packet headers.</p><h3 id="compressed-sid-and-usid" tabindex="-1">Compressed SID and uSID <a class="header-anchor" href="#compressed-sid-and-usid" aria-label="Permalink to &quot;Compressed SID and uSID&quot;">​</a></h3><p>Long SRv6 segment lists can increase packet overhead.</p><p>Compressed SID and micro-segment SRv6, uSID, reduce that overhead.</p><p>Key ideas:</p><ul><li>Normal SRv6 SID is 128 bits.</li><li>uSID can encode micro-segments in smaller chunks, such as 16-bit micro-SIDs.</li><li>uSID keeps the SRv6 programming model while reducing header size.</li><li>This helps multi-domain or long-path deployments.</li></ul><p>For AI fabrics, SRv6/uSID is interesting because it can support deterministic path placement, but it must still coexist with RoCEv2 lossless mechanisms such as DCQCN.</p><hr><h2 id="routing-protocol-comparison" tabindex="-1">Routing Protocol Comparison <a class="header-anchor" href="#routing-protocol-comparison" aria-label="Permalink to &quot;Routing Protocol Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Characteristic</th><th>BGP</th><th>RIFT</th><th>IS-IS</th></tr></thead><tbody><tr><td>IP Clos ECMP support</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Dragonfly topology support</td><td>Limited</td><td>Yes</td><td>Limited</td></tr><tr><td>Multi-tenancy options</td><td>Strong with EVPN-VXLAN</td><td>Limited</td><td>Limited</td></tr><tr><td>Convergence speed</td><td>Medium</td><td>Fast</td><td>Fast</td></tr><tr><td>Link awareness</td><td>Low by default</td><td>High</td><td>High</td></tr><tr><td>Full topology awareness</td><td>Medium</td><td>High</td><td>Medium</td></tr><tr><td>Automatic disaggregation on failure</td><td>No</td><td>Yes</td><td>No</td></tr><tr><td>Fabric configuration metadata</td><td>Limited</td><td>Yes</td><td>Limited</td></tr><tr><td>Wide ECMP / UCMP</td><td>Yes with extensions</td><td>Yes</td><td>Limited</td></tr><tr><td>Policy control</td><td>High</td><td>Lower</td><td>Medium</td></tr><tr><td>Operational maturity in DC fabrics</td><td>High</td><td>Emerging</td><td>Medium</td></tr></tbody></table><p>Decision guidance:</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Likely Fit</th></tr></thead><tbody><tr><td>Cloud-style Clos with strong policy and EVPN</td><td>eBGP</td></tr><tr><td>Fat-tree optimized IGP with fast convergence</td><td>RIFT</td></tr><tr><td>Pure IP fabric with logical path algorithms</td><td>IS-IS FlexAlgo</td></tr><tr><td>Deterministic tenant/GPU/QP path coloring in BGP fabric</td><td>BGP-DPF</td></tr><tr><td>Explicit controller-computed paths</td><td>Segment Routing / SRv6</td></tr><tr><td>Server anycast or service prefix advertisement</td><td>Server-to-ToR BGP</td></tr></tbody></table><hr><h2 id="operational-validation-checklist" tabindex="-1">Operational Validation Checklist <a class="header-anchor" href="#operational-validation-checklist" aria-label="Permalink to &quot;Operational Validation Checklist&quot;">​</a></h2><p>Routing design should be validated as a workload-facing system, not only as a reachability graph.</p><p>Checklist:</p><ul><li>Confirm backend and frontend routing domains are intentionally separated or shared.</li><li>Validate eBGP ASN allocation and AS-PATH loop prevention.</li><li>Confirm BGP unnumbered peers exchange IPv4 NLRI with IPv6 link-local next hops.</li><li>Test link failure convergence for leaf-spine and spine-super-spine paths.</li><li>Verify ECMP width for GPU prefixes.</li><li>Test BGP ADD-PATH behavior if route reflectors or path hiding are present.</li><li>Validate BGP Link Bandwidth Extended Community and weighted ECMP behavior.</li><li>Confirm minimum active peer policy for critical prefixes.</li><li>Validate BGP-DPF color assignment for tenant, GPU, QP, or SLA traffic.</li><li>Verify EVPN-VXLAN tenant route isolation with RT-2 and RT-5 routes.</li><li>Test RIFT or IS-IS convergence if using IGP alternatives.</li><li>Validate IS-IS FlexAlgo path constraints and fallback behavior.</li><li>Confirm server-to-ToR BGP withdraw behavior for service failure.</li><li>Validate controller-driven path updates against real telemetry.</li><li>Test SRv6/uSID MTU and hardware forwarding support.</li><li>Measure workload effects: NCCL latency, p99 iteration time, GPU utilization, and JCT.</li></ul>`,29)),(a(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-2638",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20model%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20test%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20signal%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20decision%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20fix%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20R%5BRouting%20model%3Cbr%2F%3EBGP%2C%20RIFT%2C%20IS-IS%2C%20SR%5D%3A%3A%3Amodel%0A%20%20%20%20P%5BPolicy%20model%3Cbr%2F%3Etenant%2C%20color%2C%20VRF%2C%20path%5D%3A%3A%3Amodel%0A%20%20%20%20F%5BFailure%20tests%3Cbr%2F%3Elink%2C%20spine%2C%20ToR%2C%20server%5D%3A%3A%3Atest%0A%20%20%20%20T%5BTelemetry%3Cbr%2F%3EECMP%20width%2C%20queues%2C%20route%20churn%5D%3A%3A%3Asignal%0A%20%20%20%20W%5BWorkload%20validation%3Cbr%2F%3ENCCL%2C%20RoCEv2%2C%20storage%5D%3A%3A%3Atest%0A%20%20%20%20D%7BDoes%20routing%20behavior%3Cbr%2F%3Eprotect%20workload%20target%3F%7D%3A%3A%3Adecision%0A%20%20%20%20A%5BAccept%20design%3Cbr%2F%3Edocument%20operating%20envelope%5D%3A%3A%3Amodel%0A%20%20%20%20X%5BRevise%20ASN%2C%20policy%2C%3Cbr%2F%3Eprotocol%2C%20path%2C%20or%20topology%5D%3A%3A%3Afix%0A%0A%20%20%20%20R%20--%3E%20P%20--%3E%20F%20--%3E%20T%20--%3E%20W%20--%3E%20D%0A%20%20%20%20D%20--%3E%7CYes%7C%20A%0A%20%20%20%20D%20--%3E%7CNo%7C%20X%0A%20%20%20%20X%20--%3E%20R%0A"})]),fallback:t(()=>[...e[10]||(e[10]=[n(" Loading... ",-1)])]),_:1})),e[22]||(e[22]=i('<hr><h2 id="chapter-summary" tabindex="-1">Chapter Summary <a class="header-anchor" href="#chapter-summary" aria-label="Permalink to &quot;Chapter Summary&quot;">​</a></h2><p>AI data center routing must support reachability, convergence, path control, and tenant isolation at the same time.</p><p>The main takeaways:</p><ul><li>eBGP remains the most common underlay choice for three-stage and five-stage Clos AI fabrics.</li><li>BGP unnumbered reduces per-link addressing and simplifies automation.</li><li>ASN allocation matters because AS-PATH behavior can prevent loops or create suboptimal paths.</li><li>BGP ADD-PATH and BGP Link Bandwidth Extended Community improve path diversity and weighted ECMP.</li><li>BGP-DPF introduces deterministic logical fabric colors for tenant, GPU, QP, or SLA traffic.</li><li>RIFT is designed for fat-tree fabrics and can also support Dragonfly-style topology awareness.</li><li>IS-IS Optimal Distributed Flooding improves convergence in dense fabrics.</li><li>IS-IS FlexAlgo can create logical routing planes using bandwidth, latency, or congestion constraints.</li><li>EVPN-VXLAN, VRFs, MIG, and dynamic ACLs are different tools for AI multi-tenancy.</li><li>Extending BGP to servers enables anycast and service prefix advertisement directly from GPU hosts.</li><li>Segment Routing and SRv6 provide explicit path programming, especially with controller-driven traffic engineering.</li><li>No routing protocol is universally best; the right answer depends on topology, scale, vendor support, operations, and workload goals.</li></ul><hr><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>eBGP</td><td>External Border Gateway Protocol</td></tr><tr><td>BGP unnumbered</td><td>BGP peering using IPv6 link-local addresses instead of numbered IPv4 point-to-point links</td></tr><tr><td>RFC 5549</td><td>Advertising IPv4 NLRI with IPv6 next hop</td></tr><tr><td>ASN</td><td>Autonomous System Number</td></tr><tr><td>AS-PATH</td><td>BGP path attribute listing ASNs traversed</td></tr><tr><td>ADD-PATH</td><td>BGP capability to advertise multiple paths for a prefix</td></tr><tr><td>BGP Link Bandwidth Extended Community</td><td>BGP community carrying bandwidth for weighted ECMP</td></tr><tr><td>DPF</td><td>Deterministic Path Forwarding</td></tr><tr><td>Fabric color</td><td>Logical fabric or path group used for deterministic forwarding</td></tr><tr><td>RIFT</td><td>Routing in Fat Trees</td></tr><tr><td>UCMP</td><td>Unequal-Cost Multipathing</td></tr><tr><td>IS-IS</td><td>Intermediate System to Intermediate System</td></tr><tr><td>FlexAlgo</td><td>IS-IS flexible algorithm for constraint-based logical topologies</td></tr><tr><td>FAD</td><td>Flexible Algorithm Definition</td></tr><tr><td>EVPN</td><td>Ethernet VPN control plane</td></tr><tr><td>VXLAN</td><td>Overlay encapsulation using VNI identifiers</td></tr><tr><td>VNI</td><td>VXLAN Network Identifier</td></tr><tr><td>MAC-VRF</td><td>Layer 2 tenant forwarding instance</td></tr><tr><td>IP-VRF</td><td>Layer 3 tenant routing instance</td></tr><tr><td>RT-2</td><td>EVPN MAC/IP route type</td></tr><tr><td>RT-5</td><td>EVPN IP prefix route type</td></tr><tr><td>MIG</td><td>Multi-Instance GPU</td></tr><tr><td>SR</td><td>Segment Routing</td></tr><tr><td>SID</td><td>Segment Identifier</td></tr><tr><td>SRH</td><td>Segment Routing Header</td></tr><tr><td>SRv6</td><td>Segment Routing over IPv6</td></tr><tr><td>uSID</td><td>Micro-segment SRv6</td></tr></tbody></table><h2 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h2><h3 id="_1-why-is-bgp-widely-adopted-for-routing-in-large-scale-ai-data-center-fabrics" tabindex="-1">1. Why is BGP widely adopted for routing in large-scale AI data center fabrics? <a class="header-anchor" href="#_1-why-is-bgp-widely-adopted-for-routing-in-large-scale-ai-data-center-fabrics" aria-label="Permalink to &quot;1. Why is BGP widely adopted for routing in large-scale AI data center fabrics?&quot;">​</a></h3><p>BGP is widely adopted because it scales well, has strong policy control, works across vendors, and has built-in loop prevention through AS-PATH.</p><p>In AI fabrics, eBGP is commonly used with unique ASNs per leaf or rack and shared ASNs at spine layers. BGP unnumbered simplifies leaf-spine peering by using IPv6 link-local addresses, while route policies control prefix advertisement, filtering, maintenance, and tenant behavior.</p><h3 id="_2-what-does-bgp-unnumbered-solve" tabindex="-1">2. What does BGP unnumbered solve? <a class="header-anchor" href="#_2-what-does-bgp-unnumbered-solve" aria-label="Permalink to &quot;2. What does BGP unnumbered solve?&quot;">​</a></h3><p>BGP unnumbered removes the need to assign IPv4 point-to-point addresses to every leaf-spine link.</p><p>The fabric uses IPv6 link-local addresses for BGP neighbor discovery and session establishment. IPv4 server prefixes can still be advertised, but the next hop is an IPv6 link-local address. This is useful in AI fabrics because the number of physical links can be very large.</p><h3 id="_3-why-does-asn-allocation-matter-in-ebgp-clos-fabrics" tabindex="-1">3. Why does ASN allocation matter in eBGP Clos fabrics? <a class="header-anchor" href="#_3-why-does-asn-allocation-matter-in-ebgp-clos-fabrics" aria-label="Permalink to &quot;3. Why does ASN allocation matter in eBGP Clos fabrics?&quot;">​</a></h3><p>ASN allocation determines how AS-PATH loop prevention behaves. If spines share an ASN and leaves use unique ASNs, BGP can reject routes that would loop through the same AS. This can also help prevent suboptimal forwarding after failures.</p><p>Poor ASN design can make troubleshooting harder or allow unexpected backup paths with bad performance.</p><h3 id="_4-how-does-bgp-dpf-help-ai-workloads" tabindex="-1">4. How does BGP-DPF help AI workloads? <a class="header-anchor" href="#_4-how-does-bgp-dpf-help-ai-workloads" aria-label="Permalink to &quot;4. How does BGP-DPF help AI workloads?&quot;">​</a></h3><p>BGP-DPF divides one physical fabric into logical colored fabrics. Traffic can be mapped to a color based on tenant, GPU ID, QP range, or SLA.</p><p>This gives deterministic path selection. It can isolate elephant flows, keep tenant traffic predictable, and align overlay tenants with underlay path colors.</p><h3 id="_5-what-are-rift-s-advantages-in-ai-fabrics" tabindex="-1">5. What are RIFT&#39;s advantages in AI fabrics? <a class="header-anchor" href="#_5-what-are-rift-s-advantages-in-ai-fabrics" aria-label="Permalink to &quot;5. What are RIFT&#39;s advantages in AI fabrics?&quot;">​</a></h3><p>RIFT is designed for fat-tree and Clos-style topologies. It provides fast convergence, topology awareness, wide ECMP, UCMP, and automatic disaggregation on failures.</p><p>It can be attractive when BGP policy is less important than topology-native convergence and fabric awareness. Its main trade-off is maturity and operational familiarity compared with eBGP.</p><h3 id="_6-how-does-is-is-flexalgo-support-workload-isolation" tabindex="-1">6. How does IS-IS FlexAlgo support workload isolation? <a class="header-anchor" href="#_6-how-does-is-is-flexalgo-support-workload-isolation" aria-label="Permalink to &quot;6. How does IS-IS FlexAlgo support workload isolation?&quot;">​</a></h3><p>IS-IS FlexAlgo computes multiple logical topologies over the same physical fabric. Each algorithm can use different constraints such as latency, bandwidth, or congestion.</p><p>This lets one workload use a low-latency plane, another use a high-bandwidth plane, and another use a low-congestion plane. It is similar in spirit to BGP-DPF, but implemented through link-state TLVs and FADs.</p><h3 id="_7-how-does-multi-tenancy-affect-ai-routing" tabindex="-1">7. How does multi-tenancy affect AI routing? <a class="header-anchor" href="#_7-how-does-multi-tenancy-affect-ai-routing" aria-label="Permalink to &quot;7. How does multi-tenancy affect AI routing?&quot;">​</a></h3><p>Multi-tenancy requires segmentation and policy at multiple layers. A tenant may need isolated GPU instances, isolated VLAN/VNI mappings, separate MAC-VRF/IP-VRF instances, and separate EVPN routes.</p><p>BGP-EVPN is commonly used because it can signal tenant MAC/IP and prefix routes at scale. Server-level features such as MIG can be combined with network-level EVPN-VXLAN to provide end-to-end GPU tenant isolation.</p><h3 id="_8-why-extend-ip-routing-to-gpu-servers" tabindex="-1">8. Why extend IP routing to GPU servers? <a class="header-anchor" href="#_8-why-extend-ip-routing-to-gpu-servers" aria-label="Permalink to &quot;8. Why extend IP routing to GPU servers?&quot;">​</a></h3><p>Server-to-ToR BGP lets GPU servers advertise service prefixes or anycast addresses directly into the fabric. If a service fails, the server can withdraw the prefix.</p><p>This makes routing more dynamic and can simplify anycast service design, but it adds operational responsibility to the server side and may require route reflectors at scale.</p><h3 id="_9-what-role-does-telemetry-play-in-routing-and-traffic-engineering" tabindex="-1">9. What role does telemetry play in routing and traffic engineering? <a class="header-anchor" href="#_9-what-role-does-telemetry-play-in-routing-and-traffic-engineering" aria-label="Permalink to &quot;9. What role does telemetry play in routing and traffic engineering?&quot;">​</a></h3><p>Telemetry gives routing controllers and operators the data needed to make path decisions. Useful signals include link utilization, queue occupancy, ECN/PFC counters, active probes, sFlow, and job scheduler placement.</p><p>Without telemetry, traffic engineering becomes static policy. With telemetry, the fabric can adapt paths to real workload and congestion state.</p><h3 id="_10-how-does-segment-routing-or-srv6-help-ai-fabrics" tabindex="-1">10. How does Segment Routing or SRv6 help AI fabrics? <a class="header-anchor" href="#_10-how-does-segment-routing-or-srv6-help-ai-fabrics" aria-label="Permalink to &quot;10. How does Segment Routing or SRv6 help AI fabrics?&quot;">​</a></h3><p>Segment Routing lets an ingress node encode a path into the packet. With a controller, GPU-to-GPU paths can be computed to avoid congestion or satisfy SLA goals.</p><p>SRv6 carries path instructions in an IPv6 Segment Routing Header. uSID reduces header overhead by using compact micro-segments. The trade-off is that SRv6 requires hardware support, MTU planning, and careful integration with RoCEv2 lossless mechanisms such as DCQCN.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc7938.html" target="_blank" rel="noreferrer">RFC 7938, Use of BGP for Routing in Large-Scale Data Centers</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc5549.html" target="_blank" rel="noreferrer">RFC 5549, Advertising IPv4 NLRI with an IPv6 Next Hop</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9692.html" target="_blank" rel="noreferrer">RFC 9692, RIFT: Routing in Fat Trees</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9350.html" target="_blank" rel="noreferrer">RFC 9350, IGP Flexible Algorithm</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9502.html" target="_blank" rel="noreferrer">RFC 9502, IGP Flexible Algorithm in IP Networks</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc8754.html" target="_blank" rel="noreferrer">RFC 8754, IPv6 Segment Routing Header</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc8986.html" target="_blank" rel="noreferrer">RFC 8986, Segment Routing over IPv6 Network Programming</a></li><li><a href="https://datatracker.ietf.org/doc/html/draft-wang-idr-dpf-00" target="_blank" rel="noreferrer">IETF draft-wang-idr-dpf, BGP Deterministic Path Forwarding</a></li></ul>',41))])}const I=d(g,[["render",m]]);export{w as __pageData,I as default};
